    public Object parseOrder(Object order, Object... optionalArgs)
    {
        Object market = Helpers.getArg(optionalArgs, 0, null);
        String marketId = this.safeString(order, "symbol");
        market = this.safeMarket(marketId, market);
        Object statuses = this.safeDict(this.options, "orderStatuses", new HashMap<String, Object>() {{}});
        String status = this.safeString(order, "status");
        String type = this.safeStringLower(order, "type"); // LIMIT, MARKET, STOP_LIMIT, STOP_MARKET
        if (Helpers.isTrue(!Helpers.isEqual(type, null)))
        {
            type = Helpers.replace(type, (String)"stop_", (String)"");
        }
        String average = this.safeString(order, "executedPrice");
        if (Helpers.isTrue(Precise.stringEq(average, "0")))
        {
            average = null;
        }
        // wallex identifies orders by clientOrderId for fetch and cancel
        String clientOrderId = this.safeString(order, "clientOrderId");
        final Object finalMarket = market;
        final Object finalType = type;
        final Object finalAverage = average;
        return this.safeOrder(new HashMap<String, Object>() {{
            put( "id", clientOrderId );
            put( "clientOrderId", clientOrderId );
            put( "timestamp", Wallex.this.parse8601(Wallex.this.safeString(order, "created_at")) );
            put( "datetime", null );
            put( "lastTradeTimestamp", null );
            put( "symbol", Helpers.GetValue(finalMarket, "symbol") );
            put( "type", finalType );
            put( "timeInForce", null );
            put( "postOnly", null );
            put( "side", Wallex.this.safeStringLower(order, "side") );
            put( "price", Wallex.this.safeString(order, "price") );
            put( "triggerPrice", Wallex.this.safeString(order, "stopPrice") );
            put( "amount", Wallex.this.safeString(order, "origQty") );
            put( "filled", Wallex.this.safeString(order, "executedQty") );
            put( "remaining", null );
            put( "cost", Wallex.this.safeString(order, "executedSum") );
            put( "average", finalAverage );
            put( "status", Wallex.this.safeString(statuses, status, status) );
            put( "fee", new HashMap<String, Object>() {{
                put( "cost", Wallex.this.safeString(order, "fee") );
                put( "currency", null );
            }} );
            put( "trades", null );
            put( "info", order );
        }}, market);
    }

    public Object sign(Object path, Object... optionalArgs)
    {
        Object api = Helpers.getArg(optionalArgs, 0, "public");
        Object method = Helpers.getArg(optionalArgs, 1, "GET");
        Object parameters = Helpers.getArg(optionalArgs, 2, new HashMap<String, Object>() {{}});
        Object headers = Helpers.getArg(optionalArgs, 3, null);
        Object body = Helpers.getArg(optionalArgs, 4, null);
        Object url = Helpers.add(Helpers.add(Helpers.GetValue(Helpers.GetValue(this.urls, "api"), "rest"), "/"), this.implodeParams(path, parameters));
        Object query = this.omit(parameters, this.extractParams(path));
        headers = new HashMap<String, Object>() {{}};
        if (Helpers.isTrue(Helpers.isEqual(api, "private")))
        {
            // wallex authenticates with the raw key in x-api-key, there is no secret and no hmac signature
            this.checkRequiredCredentials();
            Helpers.addElementToObject(headers, "X-API-KEY", this.apiKey);
        }
        if (Helpers.isTrue(Helpers.isEqual(method, "GET")))
        {
            if (Helpers.isTrue(Helpers.isGreaterThan(Helpers.getArrayLength(Helpers.objectKeys(query)), 0)))
            {
                url = Helpers.add(url, Helpers.add("?", this.urlencode(query)));
            }
        } else
        {
            body = this.json(query);
            Helpers.addElementToObject(headers, "Content-Type", "application/json");
        }
        final Object finalUrl = url;
        final Object finalMethod = method;
        final Object finalBody = body;
        final Object finalHeaders = headers;
        return new HashMap<String, Object>() {{
            put( "url", finalUrl );
            put( "method", finalMethod );
            put( "body", finalBody );
            put( "headers", finalHeaders );
        }};
    }

    public Object handleErrors(Object httpCode, Object reason, Object url, Object method, Object headers, Object body, Object response, Object requestHeaders, Object requestBody)
    {
        if (Helpers.isTrue(Helpers.isEqual(response, null)))
        {
            return null;
        }
        //
        //     { "code": 1201, "message": "invalid API key format", "result": {}, "success": false }
        //
        Object success = this.safeBool(response, "success");
        if (Helpers.isTrue(Helpers.isEqual(success, false)))
        {
            String code = this.safeString(response, "code");
            if (Helpers.isTrue(Helpers.isEqual(code, "1201")))
            {
                throw new AuthenticationError(Helpers.add(Helpers.add(this.id, " "), body)) ;
            }
            throw new ExchangeError(Helpers.add(Helpers.add(this.id, " "), body)) ;
        }
        return null;
    }
